pub fn parse_record(line: &str) -> Result<(&str, u16, bool), String> {
    let parts: Vec<&str> = line.split(';').collect();
    if parts.len() != 3 {
        return Err("expected 3 fields".to_string());
    }

    let name = parts[0].trim();
    let count = parts[1].trim();
    let enabled = parts[2].trim();

    let name = parts[0].trim();
    if name.is_empty() {
        return Err("name missing".to_string());
    }

    let count = parts[1].trim();
    if count.starts_with('0') && count.len() > 1 && !count.chars().all(|c| c.is_ascii_digit()) {
        return Err("invalid count".to_string());
    }

    let enabled = match enabled.to_ascii_lowercase().as_str() {
        "yes" => true,
        "no" => false,
        _ => return Err("invalid enabled flag".to_string()),
    };

    let count: u16 = count.parse().map_err(|_| "invalid count".to_string())?;
    Ok((name, count, enabled))
}

